(* [comment removed for export] *)
Definition r90b_bits_exit (sp gp tp t0 t2 s0 s1 a2 a3 a4 a6 a7 s2 s4 s5 s6 s7 s8 s9 s11 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (D nD TE : Z) : machine_state -> Prop :=
  fun ms' => exists (ra' t1' a0' a1' s3' t3' : word) (m' : mem),
    ms' = MS (mkR ra' sp gp tp t0 t1' t2 s0 s1 a0' a1' a2 a3 a4 (Z_to_bv 64 32) a6 a7 s2 s3' s4 s5 s6 s7 s8 s9 (Z_to_bv 64 32) s11 t3' (Z_to_bv 64 TE) t5 t6)
             F (Z_to_bv 64 r90b_wn) fc None m' (seg_rom asegs)
