(* [comment removed for export] *)
Definition r90b_words_exit (sp gp tp t0 t2 s0 s1 a2 a3 a4 a6 a7 s2 s4 s5 s6 s7 s8 s11 t5 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (D nD NW TE : Z) : machine_state -> Prop :=
  fun ms' => exists (ra' t1' a0' a1' s3' s9' s10' t3' : word) (m' : mem),
    ms' = MS (mkR ra' sp gp tp t0 t1' t2 s0 s1 a0' a1' a2 a3 a4 (Z_to_bv 64 32) a6 a7 s2 s3' s4 s5 s6 s7 s8 s9' s10' s11 t3' (Z_to_bv 64 TE) t5 (Z_to_bv 64 NW))
             F (Z_to_bv 64 r90b_re) fc None m' (seg_rom asegs)
    /\ munch [(D, D + nD)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

Lemma r90b_words : forall (n : nat) (jw : Z)
    (sp gp tp s0 s1 a2 s2 s4 s6 s7 s8 ra t1 a0 a1 s3 s9 s10 t3 : word) F fc (m : mem) (D nD S nS wpld L NW JW T4 T0 I WD A4 A6 A7 F32 : Z),
  Z.of_nat n = NW - jw -> 0 <= jw < NW -> JW = jw -> T4 = T0 - 128 * wpld * jw -> A4 = 4 * wpld -> A6 = 2^64 - 4 * wpld -> A7 = 2^64 - 128 * wpld ->
  0 <= I < WD -> 1 <= WD <= 20000 -> (WD - 1 - I) / 32 + 1 <= wpld ->
  1 <= wpld <= 626 -> 0 < D -> D mod 4 = 0 -> D + nD <= 2^47 -> (D + nD <= 0x7fff7000 \/ 0x10007fff8000 <= D) ->
  T0 mod 4 = 0 -> D + 128 * wpld * NW <= T0 + 4 * wpld -> T0 + 4 * wpld <= D + nD ->
  0 < S -> S mod 4 = 0 -> S + nS <= 2^47 -> L mod 4 = 0 -> S <= L -> L + 4 * NW <= S + nS ->
  0 < F32 -> F32 mod 4 = 0 -> F32 + 4 <= 2^47 -> (F32 + 4 <= D \/ D + nD <= F32) -> (F32 + 4 <= 0x7fff7000 \/ 0x10007fff8000 <= F32) ->
  rw_cells asegs m F32 [C4 (Z_to_bv 64 WD)] ->
  wr_at asegs m D nD -> acc asegs m D nD -> wr_at asegs m S nS -> acc asegs m S nS -> mem_inv asegs m ->
  evt asegs (r90b_words_exit sp gp tp (Z_to_bv 64 NW) (Z_to_bv 64 (-2147483648)) s0 s1 a2 (Z_to_bv 64 (18446744073709551615 - I)) (Z_to_bv 64 A4) (Z_to_bv 64 A6) (Z_to_bv 64 A7)
               s2 s4 (Z_to_bv 64 F32) s6 s7 s8 (Z_to_bv 64 2147450880) (Z_to_bv 64 L) F fc m D nD NW (T0 - 128 * wpld * NW))
    (MS (mkR ra sp gp tp (Z_to_bv 64 NW) t1 (Z_to_bv 64 (-2147483648)) s0 s1 a0 a1 a2 (Z_to_bv 64 (18446744073709551615 - I)) (Z_to_bv 64 A4) (Z_to_bv 64 32)
             (Z_to_bv 64 A6) (Z_to_bv 64 A7) s2 s3 s4 (Z_to_bv 64 F32) s6 s7 s8 s9 s10 (Z_to_bv 64 2147450880) t3 (Z_to_bv 64 T4) (Z_to_bv 64 L) (Z_to_bv 64 JW))
