Lemma r90b_rows : forall (n : nat) (i : Z)
    (sp gp tp s0 s2 s8 ra a0 a3 s3 s9 s10 t4 t5 t6 : word) F fc (m : mem) (D nD S nS wpld wpls WD WS NW F32 F48 S1 IR : Z),
  Z.of_nat n = WD - i -> 0 <= i < WD -> IR = i -> 0 <= S1 -> F48 = F32 + 16 ->
  1 <= WD <= 20000 -> 1 <= WS <= 20000 -> NW = WS / 32 -> wpld = (WD + 31) / 32 -> wpls = (WS + 31) / 32 -> nD = 4 * (wpld * WS) -> nS = 4 * (wpls * WD) ->
  0 < D -> D mod 4 = 0 -> D + nD <= 2^47 -> (D + nD <= 0x7fff7000 \/ 0x10007fff8000 <= D) ->
  0 < S -> S mod 4 = 0 -> S + nS <= 2^47 ->
  0 < F32 -> F32 mod 4 = 0 -> F32 + 20 <= 2^47 -> (F32 + 20 <= D \/ D + nD <= F32) -> (F32 + 20 <= 0x7fff7000 \/ 0x10007fff8000 <= F32) ->
  S1 mod 8 = 0 -> S1 + 64 <= 2^47 -> (S1 + 64 <= D \/ D + nD <= S1 + 16) ->
  rw_cells asegs m F32 [C4 (Z_to_bv 64 WD)] -> rw_cells asegs m F48 [C4 (Z_to_bv 64 WS)] ->
  rw_cells asegs m (S1 + 16) [C8 (Z_to_bv 64 WS)] -> rw_cells asegs m (S1 + 40) [C8 (Z_to_bv 64 (32 * NW))] ->
  rw_cells asegs m (S1 + 48) [C8 (sx32 (Z_to_bv 64 wpld))] -> rw_cells asegs m (S1 + 56) [C8 (sx32 (Z_to_bv 64 wpls))] ->
  wr_at asegs m D nD -> acc asegs m D nD -> wr_at asegs m S nS -> acc asegs m S nS -> mem_inv asegs m ->
  evt asegs (r90a_rows_exit sp gp tp s0 (Z_to_bv 64 S1) s2 (Z_to_bv 64 D) (Z_to_bv 64 F32) (Z_to_bv 64 F48) (Z_to_bv 64 S) s8 (Z_to_bv 64 2147450880) F fc m D nD)
    (MS (mkR ra sp gp tp (Z_to_bv 64 NW) (Z_to_bv 64 wpls) (Z_to_bv 64 (-2147483648)) s0 (Z_to_bv 64 S1) a0 (Z_to_bv 64 WD) (Z_to_bv 64 IR) a3
             (Z_to_bv 64 (4 * wpld)) (Z_to_bv 64 32) (Z_to_bv 64 (18446744073709551616 - 4 * wpld)) (Z_to_bv 64 (18446744073709551616 - 128 * wpld))
             s2 s3 (Z_to_bv 64 D) (Z_to_bv 64 F32) (Z_to_bv 64 F48) (Z_to_bv 64 S) s8 s9 s10
             (Z_to_bv 64 2147450880) (Z_to_bv 64 wpld) t4 t5 t6)
